import{_ as s,o as e,c as n,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2017-MAR-23 -- Ceph Tech Talks: Ceph at Scale & Writing Applications with Language Bindings","description":"","frontmatter":{"title":"2017-MAR-23 -- Ceph Tech Talks: Ceph at Scale & Writing Applications with Language Bindings","date":"2017-04-06T00:00:00.000Z","updated":"2017-04-07T00:00:00.000Z","tags":["Ceph","分布式存储","Rust 绑定","自动化部署","应用开发"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAR-23_--_Ceph_Tech_Talks_-_Ceph_at_Scale_Writing_Applications_with_Language_Bindings.md","filePath":"posts/2017/2017-MAR-23_--_Ceph_Tech_Talks_-_Ceph_at_Scale_Writing_Applications_with_Language_Bindings.md","lastUpdated":1780459816000}'),o={name:"posts/2017/2017-MAR-23_--_Ceph_Tech_Talks_-_Ceph_at_Scale_Writing_Applications_with_Language_Bindings.md"};function r(a,t,p,_,h,l){return e(),n("div",null,[...t[0]||(t[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>会议主题</strong>： Ceph 扩展规模部署技巧与应用开发</p><p><strong>参会人员</strong>： Chris Wholey（Canonical 高级存储负责人）、Chris Jones（Ceph Rust 绑定开发者）以及其他与会者</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph 扩展规模部署技巧</strong></p><ol><li><strong>Juju 工具介绍</strong>： Chris Wholey 介绍了 Canonical 开发的 Juju 工具，该工具通过 Charm（钩子）的方式，简化了 Ceph 集群的部署和配置过程。</li><li><strong>Charm 优势</strong>： Charm 允许用户轻松地将应用程序与其他应用程序进行集成，并提供丰富的配置选项，例如磁盘分区、文件系统格式、加密等。</li><li><strong>自动化升级</strong>： Chris Wholey 展示了如何使用 Juju 工具进行自动化升级，包括如何升级 Ceph 集群和 OSD 设备。</li><li><strong>跨平台部署</strong>： Juju 工具支持在物理机、虚拟机和容器等多种平台上部署 Ceph 集群。</li><li><strong>Charm 部署示例</strong>： 通过实际操作演示了 Charm 在 Amazon EC2 等平台上的部署过程。</li></ol><p><strong>二、Ceph Rust 绑定</strong></p><ol><li><strong>Rust 语言优势</strong>： Chris Jones 介绍了 Rust 语言在 Ceph 开发中的应用，Rust 语言具有内存安全、并发性能高等优点。</li><li><strong>Ceph Rust 绑定</strong>： Chris Jones 展示了 Ceph Rust 绑定的开发过程，该绑定提供了对 Ceph 库的访问，并使用 Rust 的安全特性进行封装。</li><li><strong>示例应用</strong>： Chris Jones 展示了如何使用 Ceph Rust 绑定编写一个简单的应用程序，该应用程序连接到 Ceph 集群并打印出集群的使用情况。</li><li><strong>扩展功能</strong>： Chris Jones 展示了如何使用 Rust 绑定开发新的 Ceph 客户端或功能，例如文件加密工具。</li></ol><p><strong>三、后续行动计划</strong></p><ol><li><strong>完善 Ceph Rust 绑定</strong>： Chris Jones 和 Chris Wholey 将继续完善 Ceph Rust 绑定，并提供更多功能。</li><li><strong>推广 Ceph Rust 绑定</strong>： 将 Ceph Rust 绑定推广给更多开发者，并鼓励其在 Ceph 应用开发中使用。</li></ol><p><strong>四、其他</strong></p><ol><li><strong>Q&amp;A环节</strong>： 会议期间，与会者就 Ceph 部署技巧、Rust 语言应用等问题进行了提问和讨论。</li><li><strong>下一次会议</strong>： 下一次 SEF 技术研讨会将于 4 月 27 日举行。</li></ol><p><strong>关键词</strong>： Ceph、Juju、Charm、Rust、内存安全、并发性能、自动化升级、跨平台部署、Ceph Rust 绑定、文件加密</p>',14)])])}const u=s(o,[["render",r]]);export{C as __pageData,u as default};
